<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Personal Expense Tracker</title>
  <style>
    :root {
      --bg: #f4f7fb;
      --card: #ffffff;
      --text: #1d2939;
      --muted: #667085;
      --line: #dce3ed;
      --accent: #2563eb;
      --danger: #c81e1e;
      --danger-bg: #fee2e2;
      --success: #0f766e;
    }

    * { box-sizing: border-box; }

    body {
      margin: 0;
      font-family: Arial, Helvetica, sans-serif;
      color: var(--text);
      background: var(--bg);
    }

    main {
      width: min(960px, calc(100% - 32px));
      margin: 32px auto;
    }

    h1 {
      margin: 0 0 22px;
      font-size: 1.8rem;
    }

    h2 {
      margin: 0 0 14px;
      font-size: 1.1rem;
    }

    .card {
      background: var(--card);
      border: 1px solid var(--line);
      border-radius: 10px;
      padding: 20px;
      margin-bottom: 18px;
      box-shadow: 0 2px 8px rgba(20, 35, 60, 0.04);
    }

    .form-grid,
    .filter-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 14px;
      align-items: end;
    }

    label {
      display: block;
      color: var(--muted);
      font-size: 0.86rem;
      font-weight: bold;
    }

    input,
    select,
    button {
      font: inherit;
    }

    input,
    select {
      width: 100%;
      margin-top: 6px;
      padding: 10px;
      min-height: 41px;
      border: 1px solid #bfc9d7;
      border-radius: 6px;
      background: #fff;
      color: var(--text);
    }

    button {
      min-height: 41px;
      padding: 10px 15px;
      border: 0;
      border-radius: 6px;
      cursor: pointer;
      font-weight: bold;
    }

    #add-expense {
      width: 100%;
      color: white;
      background: var(--accent);
    }

    #add-expense:hover {
      background: #1d4ed8;
    }

    #form-error {
      min-height: 1.2em;
      margin: 12px 0 0;
      color: var(--danger);
      font-size: 0.9rem;
      font-weight: bold;
    }

    .summary {
      display: grid;
      grid-template-columns: 1fr 2fr;
      gap: 16px;
      margin-bottom: 18px;
    }

    .total-box,
    .category-box {
      border: 1px solid var(--line);
      border-radius: 8px;
      padding: 16px;
      background: #fafcff;
    }

    .total-label {
      color: var(--muted);
      font-size: 0.9rem;
    }

    #total {
      display: block;
      margin-top: 5px;
      color: var(--success);
      font-size: 1.9rem;
      font-weight: bold;
    }

    .category-totals {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 8px;
    }

    .cat-total {
      padding: 8px;
      border-radius: 5px;
      background: #eef4ff;
      color: #24406f;
      font-size: 0.85rem;
      text-align: center;
    }

    .expense-list {
      display: grid;
      gap: 10px;
    }

    .expense {
      display: grid;
      grid-template-columns: 120px 1fr 130px auto;
      gap: 12px;
      align-items: center;
      padding: 14px;
      border: 1px solid var(--line);
      border-radius: 8px;
      background: white;
    }

    .expense-amount {
      font-weight: bold;
      color: var(--success);
    }

    .expense-category {
      text-transform: capitalize;
      font-weight: bold;
    }

    .expense-date,
    .expense-note {
      color: var(--muted);
      font-size: 0.9rem;
    }

    .expense-details {
      min-width: 0;
    }

    .expense-note {
      margin-top: 3px;
      overflow-wrap: anywhere;
    }

    .exp-del {
      min-height: auto;
      padding: 8px 11px;
      color: white;
      background: var(--danger);
    }

    .exp-del:hover {
      background: #a91515;
    }

    .empty-state {
      margin: 0;
      padding: 22px;
      color: var(--muted);
      text-align: center;
      border: 1px dashed var(--line);
      border-radius: 8px;
    }

    @media (max-width: 700px) {
      .form-grid,
      .filter-grid {
        grid-template-columns: 1fr 1fr;
      }

      .summary {
        grid-template-columns: 1fr;
      }

      .category-totals {
        grid-template-columns: 1fr 1fr;
      }

      .expense {
        grid-template-columns: 1fr auto;
      }

      .expense-details,
      .expense-date {
        grid-column: 1;
      }

      .exp-del {
        grid-column: 2;
        grid-row: 1 / span 3;
      }
    }

    @media (max-width: 430px) {
      .form-grid,
      .filter-grid,
      .category-totals {
        grid-template-columns: 1fr;
      }
    }
  </style>
</head>
<body>
  <main>
    <h1>Personal Expense Tracker</h1>

    <section class="card" aria-labelledby="add-heading">
      <h2 id="add-heading">Add an Expense</h2>
      <form id="expense-form" novalidate>
        <div class="form-grid">
          <label>
            Amount
            <input id="amount" type="number" min="0.01" step="0.01" inputmode="decimal" placeholder="0.00">
          </label>

          <label>
            Category
            <select id="category">
              <option value="groceries">Groceries</option>
              <option value="transport">Transport</option>
              <option value="bills">Bills</option>
              <option value="fun">Fun</option>
            </select>
          </label>

          <label>
            Date
            <input id="date" type="date">
          </label>

          <label>
            Note (optional)
            <input id="note" type="text" maxlength="200" placeholder="What was this for?">
          </label>
        </div>
        <p id="form-error" role="alert" aria-live="polite"></p>
        <button id="add-expense" type="submit">Add Expense</button>
      </form>
    </section>

    <section class="card" aria-labelledby="filter-heading">
      <h2 id="filter-heading">Filters</h2>
      <div class="filter-grid">
        <label>
          Category
          <select id="filter-category">
            <option value="all">All categories</option>
            <option value="groceries">Groceries</option>
            <option value="transport">Transport</option>
            <option value="bills">Bills</option>
            <option value="fun">Fun</option>
          </select>
        </label>

        <label>
          From date
          <input id="filter-from" type="date">
        </label>

        <label>
          To date
          <input id="filter-to" type="date">
        </label>
      </div>
    </section>

    <section class="card" aria-labelledby="summary-heading">
      <h2 id="summary-heading">Visible Expense Summary</h2>
      <div class="summary">
        <div class="total-box">
          <span class="total-label">Visible total</span>
          <output id="total">0.00</output>
        </div>

        <div class="category-box">
          <span class="total-label">By category</span>
          <div class="category-totals" style="margin-top: 10px;">
            <div class="cat-total" data-cat="groceries">Groceries: 0.00</div>
            <div class="cat-total" data-cat="transport">Transport: 0.00</div>
            <div class="cat-total" data-cat="bills">Bills: 0.00</div>
            <div class="cat-total" data-cat="fun">Fun: 0.00</div>
          </div>
        </div>
      </div>
    </section>

    <section class="card" aria-labelledby="expenses-heading">
      <h2 id="expenses-heading">Expenses</h2>
      <div id="expense-list" class="expense-list"></div>
    </section>
  </main>

  <script>
    (function () {
      "use strict";

      var STORAGE_KEY = "personal-expense-tracker-expenses";
      var categories = ["groceries", "transport", "bills", "fun"];

      var form = document.getElementById("expense-form");
      var amountInput = document.getElementById("amount");
      var categoryInput = document.getElementById("category");
      var dateInput = document.getElementById("date");
      var noteInput = document.getElementById("note");
      var errorElement = document.getElementById("form-error");
      var filterCategory = document.getElementById("filter-category");
      var filterFrom = document.getElementById("filter-from");
      var filterTo = document.getElementById("filter-to");
      var list = document.getElementById("expense-list");
      var total = document.getElementById("total");

      var expenses = loadExpenses();

      function loadExpenses() {
        try {
          var saved = JSON.parse(localStorage.getItem(STORAGE_KEY));
          if (!Array.isArray(saved)) return [];
          return saved.filter(function (expense) {
            return expense &&
              typeof expense.id === "string" &&
              typeof expense.category === "string" &&
              categories.indexOf(expense.category) !== -1 &&
              typeof expense.date === "string" &&
              Number.isFinite(Number(expense.amount)) &&
              Number(expense.amount) > 0;
          }).map(function (expense) {
            return {
              id: expense.id,
              amount: Number(expense.amount),
              category: expense.category,
              date: expense.date,
              note: typeof expense.note === "string" ? expense.note : ""
            };
          });
        } catch (error) {
          return [];
        }
      }

      function saveExpenses() {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(expenses));
      }

      function formatAmount(value) {
        return Number(value).toFixed(2);
      }

      function matchesFilters(expense) {
        var selectedCategory = filterCategory.value;
        var from = filterFrom.value;
        var to = filterTo.value;

        if (selectedCategory !== "all" && expense.category !== selectedCategory) {
          return false;
        }
        if (from && expense.date < from) {
          return false;
        }
        if (to && expense.date > to) {
          return false;
        }
        return true;
      }

      function render() {
        list.innerHTML = "";

        var visibleExpenses = expenses.filter(matchesFilters);
        var visibleTotal = 0;
        var categoryTotals = {
          groceries: 0,
          transport: 0,
          bills: 0,
          fun: 0
        };

        visibleExpenses.forEach(function (expense) {
          visibleTotal += expense.amount;
          categoryTotals[expense.category] += expense.amount;

          var row = document.createElement("article");
          row.className = "expense";
          row.dataset.id = expense.id;

          var amount = document.createElement("div");
          amount.className = "expense-amount";
          amount.textContent = formatAmount(expense.amount);

          var details = document.createElement("div");
          details.className = "expense-details";

          var category = document.createElement("div");
          category.className = "expense-category";
          category.textContent = expense.category;

          details.appendChild(category);

          if (expense.note) {
            var note = document.createElement("div");
            note.className = "expense-note";
            note.textContent = expense.note;
            details.appendChild(note);
          }

          var date = document.createElement("div");
          date.className = "expense-date";
          date.textContent = expense.date;

          var deleteButton = document.createElement("button");
          deleteButton.type = "button";
          deleteButton.className = "exp-del";
          deleteButton.textContent = "Delete";
          deleteButton.setAttribute("aria-label", "Delete expense");

          deleteButton.addEventListener("click", function () {
            expenses = expenses.filter(function (item) {
              return item.id !== expense.id;
            });
            saveExpenses();
            render();
          });

          row.appendChild(amount);
          row.appendChild(details);
          row.appendChild(date);
          row.appendChild(deleteButton);
          list.appendChild(row);
        });

        if (visibleExpenses.length === 0) {
          var empty = document.createElement("p");
          empty.className = "empty-state";
          empty.textContent = expenses.length ? "No expenses match the current filters." : "No expenses added yet.";
          list.appendChild(empty);
        }

        total.textContent = formatAmount(visibleTotal);

        categories.forEach(function (category) {
          var categoryElement = document.querySelector('.cat-total[data-cat="' + category + '"]');
          categoryElement.textContent =
            category.charAt(0).toUpperCase() + category.slice(1) + ": " +
            formatAmount(categoryTotals[category]);
        });
      }

      form.addEventListener("submit", function (event) {
        event.preventDefault();

        var rawAmount = amountInput.value.trim();
        var amount = Number(rawAmount);
        var date = dateInput.value;

        if (rawAmount === "" || !Number.isFinite(amount) || amount <= 0) {
          errorElement.textContent = "Please enter an amount greater than zero.";
          amountInput.focus();
          return;
        }

        if (!date) {
          errorElement.textContent = "Please choose a date.";
          dateInput.focus();
          return;
        }

        errorElement.textContent = "";

        expenses.unshift({
          id: String(Date.now()) + "-" + Math.random().toString(16).slice(2),
          amount: amount,
          category: categoryInput.value,
          date: date,
          note: noteInput.value.trim()
        });

        saveExpenses();
        amountInput.value = "";
        noteInput.value = "";
        render();
        amountInput.focus();
      });

      [filterCategory, filterFrom, filterTo].forEach(function (control) {
        control.addEventListener("change", render);
        control.addEventListener("input", render);
      });

      render();
    })();
  </script>
</body>
</html>
